Contract ManageLibrarianCRUDService::createLibrarian(librarianid:String,name:String,password:String): Boolean {

            precondition:
          obs:Set(Librarian) = Librarian.allInstance()->select(o | o.LibrarianID = librarianid) obs.isEmpty() = true

            postcondition:
          let ob:Librarian in let isCreated:Boolean = ob.oclIsNew() in ob.LibrarianID = librarianid and ob.Name = name and ob.Password = password and Librarian.allInstance()->includes(ob) and result = isCreated

        }
